      [1,"Spiser du her, eller skal det med?","For here or to take away?","Здесь или с собой?","Тут чи з собою?","Na miejscu czy na wynos?","Serviți aici sau la pachet?"],
      [1,"Stor eller lille?","Large or small?","Большой или маленький?","Великий чи маленький?","Duża czy mała?","Mare sau mică?"],
      [1,"Vil du have mælk i?","Would you like milk in it?","С молоком?","З молоком?","Z mlekiem?","Doriți cu lapte?"],
      [2,"Det er selvbetjening.","It's self-service.","Здесь самообслуживание.","Тут самообслуговування.","Tu jest samoobsługa.","Aici este autoservire."],
      [2,"Frokosten er klar klokken 12.","Lunch is ready at 12.","Обед готов в 12.","Обід готовий о 12.","Obiad będzie gotowy o 12.","Prânzul este gata la ora 12."],
      [2,"Fyld salatbaren op.","Refill the salad bar.","Пополните салат-бар.","Поповніть салат-бар.","Proszę uzupełnić bar sałatkowy.","Completați bufetul de salate."],
      [2,"Der skal mere brød på buffeten.","The buffet needs more bread.","На шведский стол нужно ещё хлеба.","На шведський стіл треба ще хліба.","Trzeba dołożyć chleba na bufet.","Trebuie mai multă pâine la bufet."],
      [2,"Hvor mange spiser i dag?","How many are eating today?","Сколько человек сегодня ест?","Скільки людей сьогодні їсть?","Ile osób dziś je?","Câte persoane mănâncă azi?"],
      [2,"Bakkerne skal stilles her.","Trays go here.","Подносы ставят сюда.","Таці ставлять сюди.","Tace odstawia się tutaj.","Tăvile se pun aici."],
      [3,"Kaffen er lige blevet lavet.","The coffee is freshly made.","Кофе только что сварен.","Кава щойно зварена.","Kawa jest świeżo zaparzona.","Cafeaua este proaspăt făcută."],
      [3,"Vi har vegetarisk mad i dag.","We have vegetarian food today.","Сегодня есть вегетарианская еда.","Сьогодні є вегетаріанська їжа.","Dziś mamy danie wegetariańskie.","Azi avem mâncare vegetariană."]
